:root {
  --bg-base: #0a0a0a;
  --bg-surface: #111111;
  --bg-card: #1f1f1f;
  --border: #2a2a2a;
  --text: #fafafa;
  --text-muted: #a1a1aa;
  --accent: #0ea5e9;
  --success: #22c55e;
  --danger: #ef4444;
  --warning: #f59e0b;

  /* Uma cor por fonte de receita — a mesma em pílula, gráfico e avatar. */
  --src-empresa: #0ea5e9;
  --src-impressionart: #8b5cf6;
  --src-moto: #f59e0b;
  --src-mos: #22c55e;

  --fonte: 'Manrope', sans-serif;
  --fonte-titulo: 'Sora', sans-serif;
  --fonte-mono: 'JetBrains Mono', monospace;
}

body { background: var(--bg-base); color: var(--text); font-family: var(--fonte); }

/* Número em tabela, card ou badge nunca "dança" ao atualizar. */
.bs-num { font-variant-numeric: tabular-nums; }

.bs-anual {
  width: min(760px, 100%);
  padding: 20px; border: 1px solid var(--border); border-radius: 12px; background: var(--bg-surface);
}
.bs-anual-titulo {
  margin-bottom: 12px;
  font-family: var(--fonte-titulo); font-size: 15px; font-weight: 600; color: var(--text);
}

/* Legenda em HTML, não a do Chart.js: usa a tipografia do painel, quebra em
   várias linhas no celular e não rouba altura do canvas. */
.bs-anual-legenda { display: flex; flex-wrap: wrap; gap: 8px 16px; margin-bottom: 16px; }
.bs-anual-leg { display: flex; align-items: center; gap: 6px; font-size: 11px; color: var(--text-muted); }
.bs-anual-leg i { width: 8px; height: 8px; border-radius: 999px; }

/* Altura fixa com maintainAspectRatio: false — senão o Chart.js estica a
   altura conforme a largura e o painel dança a cada resize. */
.bs-anual-tela { position: relative; height: 260px; }
@media (min-width: 768px) { .bs-anual-tela { height: 320px; } }

